using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
using System.Collections.Generic;
static class CreateIcon {
 static GraphicsPath Round(float x,float y,float w,float h,float r){GraphicsPath p=new GraphicsPath();float d=r*2;p.AddArc(x,y,d,d,180,90);p.AddArc(x+w-d,y,d,d,270,90);p.AddArc(x+w-d,y+h-d,d,d,0,90);p.AddArc(x,y+h-d,d,d,90,90);p.CloseFigure();return p;}
 static GraphicsPath Snake(){GraphicsPath p=new GraphicsPath();p.AddBezier(90,48,90,35,166,35,166,51);p.AddLine(166,51,166,102);p.AddBezier(166,102,166,115,158,120,146,120);p.AddLine(146,120,109,120);p.AddBezier(109,120,91,120,84,128,84,145);p.AddLine(84,145,84,158);p.AddLine(84,158,65,158);p.AddBezier(65,158,43,158,39,147,39,127);p.AddLine(39,127,39,107);p.AddBezier(39,107,39,89,50,85,65,85);p.AddLine(65,85,133,85);p.AddLine(133,85,133,78);p.AddLine(133,78,90,78);p.CloseFigure();return p;}
 static Bitmap Render(int size){Bitmap high=new Bitmap(1024,1024,PixelFormat.Format32bppArgb);using(Graphics g=Graphics.FromImage(high)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(4,4);using(var bg=Round(8,8,240,240,55))using(var fill=new LinearGradientBrush(new PointF(20,15),new PointF(235,246),Color.FromArgb(27,54,90),Color.FromArgb(9,22,43)))g.FillPath(fill,bg);using(var border=Round(9,9,238,238,54))using(var pen=new Pen(Color.FromArgb(68,143,184,231),1.5f))g.DrawPath(pen,border);
  using(var blue=Snake())using(var brush=new LinearGradientBrush(new PointF(60,40),new PointF(150,155),Color.FromArgb(95,183,236),Color.FromArgb(38,119,186)))g.FillPath(brush,blue);
  g.TranslateTransform(256,256);g.RotateTransform(180);using(var yellow=Snake())using(var brush=new LinearGradientBrush(new PointF(60,40),new PointF(150,155),Color.FromArgb(255,224,126),Color.FromArgb(246,177,55)))g.FillPath(brush,yellow);g.ResetTransform();g.ScaleTransform(4,4);
  using(var eye=new SolidBrush(Color.FromArgb(17,43,69))){g.FillEllipse(eye,104,51,9,9);g.FillEllipse(eye,143,196,9,9);}using(var badge=new SolidBrush(Color.FromArgb(30,65,97)))g.FillEllipse(badge,182,178,44,44);using(var pen=new Pen(Color.FromArgb(164,231,249),3.7f)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawArc(pen,193,188,23,24,22,250);}using(var arrow=new SolidBrush(Color.FromArgb(164,231,249)))g.FillPolygon(arrow,new[]{new PointF(210,185),new PointF(219,193),new PointF(207,195)});
 }Bitmap result=new Bitmap(size,size,PixelFormat.Format32bppArgb);using(Graphics g=Graphics.FromImage(result)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;g.DrawImage(high,new Rectangle(0,0,size,size),0,0,1024,1024,GraphicsUnit.Pixel);}high.Dispose();return result;}
 static int Main(string[] args){string root=args[0];Directory.CreateDirectory(root);int[] sizes={16,20,24,32,40,48,64,96,128,256};List<byte[]> images=new List<byte[]>();foreach(int size in sizes)using(Bitmap b=Render(size))using(var memory=new MemoryStream()){b.Save(memory,ImageFormat.Png);images.Add(memory.ToArray());if(size==256)b.Save(Path.Combine(root,"PythonManager.png"),ImageFormat.Png);}using(var writer=new BinaryWriter(File.Create(Path.Combine(root,"PythonManager.ico")))){writer.Write((ushort)0);writer.Write((ushort)1);writer.Write((ushort)sizes.Length);uint offset=(uint)(6+16*sizes.Length);for(int i=0;i<sizes.Length;i++){writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((byte)0);writer.Write((byte)0);writer.Write((ushort)1);writer.Write((ushort)32);writer.Write((uint)images[i].Length);writer.Write(offset);offset+=(uint)images[i].Length;}foreach(byte[] image in images)writer.Write(image);}using(Bitmap b=Render(512))b.Save(Path.Combine(root,"PythonManager-preview.png"),ImageFormat.Png);return 0;}
}
